INSERT INTO `cursos` VALUES (5,4,'Curso Completo de Java','Aprende Java desde cero hasta Programación Orientada a Objetos. Tipos de datos, estructuras de control, excepciones, colecciones y POO completo.','40',1,'2026-08-03 11:37:24','2026-08-03 11:52:30'),(6,3,'Curso Completo de Python','Domina Python desde lo básico hasta programación avanzada. Aprende sintaxis, funciones, orientación a objetos, manejo de archivos y librerías populares.','40',1,'2026-08-03 11:56:43','2026-08-03 11:56:43'),(7,7,'Curso Completo de MySQL','Aprende MySQL desde SQL básico hasta optimización. Domina consultas, índices, procedimientos almacenados y mejores prácticas de bases de datos.','35',1,'2026-08-03 11:56:43','2026-08-03 11:56:43'),(8,NULL,'Curso Completo de HTML y CSS','Aprende HTML y CSS desde cero. Domina la estructura web, estilos, layouts modernos y diseño responsive para crear sitios web profesionales.','30',1,'2026-08-03 11:57:39','2026-08-03 11:57:39'),(9,NULL,'Curso Completo de JavaScript','Domina JavaScript desde variables y funciones hasta conceptos avanzados. Aprende a crear aplicaciones web interactivas y dinámicas.','40',1,'2026-08-03 11:57:39','2026-08-03 11:57:39'),(10,13,'Curso Completo de C#','Domina C# desde lo básico hasta programación avanzada. Aprende .NET, LINQ, async/await y construcción de aplicaciones robustas.','45',1,'2026-08-03 12:04:52','2026-08-03 12:45:03');
