CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_alta_usuario`(
  IN p_email VARCHAR(255),
  IN p_password_hash VARCHAR(255),
  IN p_nombre VARCHAR(100),
  IN p_apellido VARCHAR(100),
  IN p_dni BIGINT,
  IN p_telefono VARCHAR(20),
  IN p_activo TINYINT,
  OUT p_resultado TINYINT,
  OUT p_usuario_id INT
)
BEGIN
  IF EXISTS (SELECT 1 FROM usuarios WHERE email = p_email) THEN
    SET p_resultado = 0;
    SET p_usuario_id = -1;
  ELSE
    INSERT INTO usuarios (email, password_hash, nombre, apellido, dni, telefono, activo)
    VALUES (p_email, p_password_hash, p_nombre, p_apellido, p_dni, p_telefono, p_activo);
    SET p_resultado = 1;
    SET p_usuario_id = LAST_INSERT_ID();
  END IF;

END ;;
DELIMITER ;
