BEGIN
  DECLARE v_usuario_id INT;
  SELECT id INTO v_usuario_id FROM usuarios WHERE email = p_email LIMIT 1;
  UPDATE inscripciones SET activo = 0 WHERE usuario_id = v_usuario_id AND curso_id = p_curso_id;
