CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_codigo_verificacion`(IN p_dni BIGINT, IN p_codigo VARCHAR(6), IN p_minutos_expiracion INT)
BEGIN
  DELETE FROM codigos_verificacion WHERE dni = p_dni;
  INSERT INTO codigos_verificacion (dni, codigo, fecha_expiracion)
  VALUES (p_dni, p_codigo, DATE_ADD(NOW(), INTERVAL p_minutos_expiracion MINUTE));
END ;;
