CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_verificar_codigo_verificacion`(IN p_dni BIGINT, IN p_codigo VARCHAR(6), OUT p_resultado TINYINT)
BEGIN
  DECLARE v_expiracion DATETIME;

  SELECT fecha_expiracion INTO v_expiracion FROM codigos_verificacion
  WHERE dni = p_dni AND codigo = p_codigo LIMIT 1;

  IF v_expiracion IS NULL THEN
    SET p_resultado = 0;
  ELSEIF NOW() > v_expiracion THEN
    SET p_resultado = -1;
  ELSE
    UPDATE usuarios SET activo = 1 WHERE dni = p_dni;
    DELETE FROM codigos_verificacion WHERE dni = p_dni AND codigo = p_codigo;
    SET p_resultado = 1;
  END IF;
END ;;
DELIMITER ;
